lunch.source:
import { chat as chat_module } from adapters; chat = connect chat_module
function tally(i: <chat-[:Interaction]->>) { return i.Id }
listen to chat-[h:Channels WHERE h.Name == "office"]->-[m:Messages WHERE m.Topic == "lunch-poll" AND m.`Posted At` WITHIN 3d]->-[i:Interactions WHERE i.Value != "skip"]-> fire tally

echo.source:
import { chat as chat_module } from adapters; chat = connect chat_module
function echo(i: <chat-[:Interaction]->>) { return i.Id }
listen to chat-[:Channels]->-[m:Messages]->-[i:Interactions WHERE i.Value == m.Topic]-> fire echo

changes.source:
import { at as at_module } from adapters; at = connect at_module
function changed(x: <at-[:Change]->>) { return x.Kind }
listen to at-[b:Bases WHERE b.Name == "Finance"]->-[t:Tables WHERE t.Name == "Expenses"]->-[x:Changes WHERE x.Kind == "created"]-> fire changed

invoices.source:
import { gmail as gmail_module } from adapters; mail = connect gmail_module
function filed(e: <mail-[:Message]->>) { return e.Subject }
listen to mail-[e:Messages WHERE e.Query == "from:acme" AND e.Subject CONTAINS "invoice"]-> fire filed

keyed.source:
import { inbox as inbox_module } from adapters; box = connect inbox_module
function filed(e: <box-[:Email]->>) { return e.Subject }
listen to box-[e:Emails WHERE e.Key == "deals"]-> fire filed

negated.source:
import { chat as chat_module } from adapters; chat = connect chat_module
function tally(i: <chat-[:Interaction]->>) { return i.Id }
listen to chat-[:Channels]->-[:Messages]->-[i:Interactions WHERE -i.Score < 1]-> fire tally

stars.source:
import { chat as chat_module } from adapters; chat = connect chat_module
function starred(s: <chat-[:Star]->>) { return s.Id }
listen to chat-[c:Channels WHERE c.Name == "office"]->-[m:Messages WHERE m.Topic == "lunch-poll"]->-[s:Stars WHERE s.Value == "yes"]-> fire starred

nested.source:
import { fs as fs_module } from adapters; fs = connect fs_module
function filed(f: <fs-[:File]->>) { return f.Id }
listen to fs-[a:Folders WHERE a.Name == "root"]->-[b:Folders WHERE b.Name == "docs"]->-[:Files]-> fire filed

customers.source:
import { pay as pay_module } from adapters; pay = connect pay_module
function welcomed(c: <pay-[:CustomerChange]->>) { return c.Kind }
listen to pay-[u:Customers WHERE u.Name == "Acme"]->-[c:Changes WHERE c.Kind == "created"]-> fire welcomed

moved.source:
import { rows as rows_module } from adapters; rows = connect rows_module
function moved(c: <rows-[:`Candidates Change`]->>) { return c.Current.Stage }
listen to rows-[t:Tables WHERE t.Name == "Candidates"]->-[c:Changes WHERE c.Current.Stage == "Interview" AND c.Previous.Stage != "Interview"]-> fire moved
